#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up the "opentui-site-dispatch" GitHub App that app release workflows
# use to send repository_dispatch app-released to andycmaj/opentui-app. The
# private key goes from the downloaded .pem file straight into `gh secret set`:
# it is never printed, pasted, or copied anywhere else.

TOTAL_STAGES=5

OWNER=andycmaj
SITE_REPO=opentui-app
APP_NAME=opentui-site-dispatch
APP_REPOS=(riker ghdash kube-tui tilt-tui)
API=https://api.github.com

for tool in gh jq openssl curl; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required\n' "$tool" >&2; exit 1; }
done
gh auth status >/dev/null 2>&1 || { printf 'Run gh auth login first\n' >&2; exit 1; }

b64url() { openssl base64 -A | tr '+/' '-_' | tr -d '='; }

# app_jwt prints a 9-minute JWT signed with the App's key (what GitHub wants
# before it hands out installation tokens). Never echoed to the screen.
app_jwt() {
  local now header payload sig
  now=$(date +%s)
  header=$(printf '{"alg":"RS256","typ":"JWT"}' | b64url)
  payload=$(printf '{"iat":%d,"exp":%d,"iss":"%s"}' $((now - 60)) $((now + 540)) "$SITE_APP_CLIENT_ID" | b64url)
  sig=$(printf '%s.%s' "$header" "$payload" | openssl dgst -sha256 -sign "$PEM_PATH" -binary | b64url)
  printf '%s.%s.%s' "$header" "$payload" "$sig"
}

# api METHOD PATH AUTH [BODY]: prints the response body, fails on non-2xx.
api() {
  local method="$1" path="$2" auth="$3" body="${4:-}" out code
  out=$(mktemp)
  code=$(curl -sS -o "$out" -w '%{http_code}' -X "$method" \
    -H "Accept: application/vnd.github+json" -H "Authorization: Bearer $auth" \
    -H "X-GitHub-Api-Version: 2022-11-28" ${body:+-d "$body"} "$API$path")
  cat "$out"; rm -f "$out"
  [[ "$code" == 2* ]]
}

banner "Site dispatch GitHub App"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create the GitHub App"
say "GitHub opens the new-App form with every setting filled in. Check it:"
open_url "https://github.com/settings/apps/new?name=${APP_NAME}&description=Lets%20app%20release%20workflows%20tell%20the%20opentui-apps%20site%20to%20rebuild&url=https://andycmaj.github.io/opentui-app/&public=false&webhook_active=false&contents=write"
step "GitHub App name: ${APP_NAME}. Homepage URL: https://andycmaj.github.io/opentui-app/"
step "Webhook: 'Active' is UNchecked (no webhook URL needed)"
step "Repository permissions: Contents = Read and write (Metadata = Read-only is added for you). Nothing else."
step "Where can this GitHub App be installed? 'Only on this account'"
step "Click 'Create GitHub App'"
step "On the App's page (General → About), copy the Client ID (starts with Iv)"
note "The Client ID is not secret. Already made the App? Its page is https://github.com/settings/apps/${APP_NAME}"
current=$(gh variable get SITE_APP_CLIENT_ID -R "$OWNER/${APP_REPOS[0]}" 2>/dev/null || true)
[[ -n "$current" ]] && note "Current SITE_APP_CLIENT_ID on ${APP_REPOS[0]}: $current (Enter keeps it)"
while :; do
  ask SITE_APP_CLIENT_ID "Paste the Client ID:"
  [[ -z "$SITE_APP_CLIENT_ID" && -n "$current" ]] && SITE_APP_CLIENT_ID="$current"
  [[ "$SITE_APP_CLIENT_ID" =~ ^Iv[A-Za-z0-9.]+$ ]] && break
  warn "That doesn't look like a Client ID (Iv…). Not the numeric App ID."
done

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Generate the private key"
open_url "https://github.com/settings/apps/${APP_NAME}#private-key"
step "Scroll to 'Private keys' and click 'Generate a private key'"
step "Your browser downloads ${APP_NAME}.<date>.private-key.pem"
note "Don't open it or paste it anywhere: this wizard reads it from the file."
pause "Press Enter once it has downloaded"
newest=$(ls -t "$HOME"/Downloads/"${APP_NAME}".*.private-key.pem 2>/dev/null | head -n1 || true)
while :; do
  if [[ -n "$newest" ]]; then
    printf '  %sPath to the .pem%s %s[Enter: %s]%s ' "$BOLD" "$RESET" "$DIM" "$newest" "$RESET"
  else
    printf '  %sPath to the .pem:%s ' "$BOLD" "$RESET"
  fi
  read -r PEM_PATH || true
  PEM_PATH="${PEM_PATH:-$newest}"
  PEM_PATH="${PEM_PATH/#\~/$HOME}"
  if [[ -f "$PEM_PATH" ]] && head -n1 "$PEM_PATH" | grep -q -- '-----BEGIN .*PRIVATE KEY-----'; then
    printf '  %s✓ found a private key%s (contents not shown)\n' "$GREEN" "$RESET"
    break
  fi
  warn "No PEM private key at '$PEM_PATH'"
done
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Install the App on ${SITE_REPO} only"
if ! app_json=$(api GET /app "$(app_jwt)"); then
  warn "GitHub rejected the Client ID + key pair:"; printf '%s\n' "$app_json" | jq -r '.message // .' | sed 's/^/    /'
  exit 1
fi
APP_SLUG=$(jq -r .slug <<<"$app_json")
perms=$(jq -c .permissions <<<"$app_json")
printf '  %s✓ key works%s for App %s, permissions %s\n' "$GREEN" "$RESET" "$APP_SLUG" "$perms"
[[ "$perms" == '{"contents":"write","metadata":"read"}' ]] \
  || warn "Expected only contents:write + metadata:read. Fix it under Permissions & events before installing."
open_url "https://github.com/apps/${APP_SLUG}/installations/new"
step "Install on your account (${OWNER})"
step "Choose 'Only select repositories' → ${SITE_REPO}. Nothing else."
step "Click 'Install'"
pause "Press Enter once it's installed"
say "Checking: mint a token the way the release workflows will, and see what it reaches."
until inst=$(api GET "/repos/$OWNER/$SITE_REPO/installation" "$(app_jwt)"); do
  warn "Not installed on $OWNER/$SITE_REPO yet ($(jq -r '.message // "?"' <<<"$inst"))."
  pause "Install it, then press Enter to check again"
done
inst_id=$(jq -r .id <<<"$inst")
tok_json=$(api POST "/app/installations/$inst_id/access_tokens" "$(app_jwt)" \
  "{\"repositories\":[\"$SITE_REPO\"],\"permissions\":{\"contents\":\"write\"}}")
itoken=$(jq -r .token <<<"$tok_json")
repos=$(api GET /installation/repositories "$itoken" | jq -r '[.repositories[].full_name] | join(", ")')
api DELETE /installation/token "$itoken" >/dev/null || true
unset itoken
printf '  %s✓ minted and revoked%s a token (contents:%s, expires in ≤1h) that reaches: %s\n' \
  "$GREEN" "$RESET" "$(jq -r .permissions.contents <<<"$tok_json")" "$repos"
[[ "$(jq -r .repository_selection <<<"$inst")" == "selected" && "$repos" == "$OWNER/$SITE_REPO" ]] \
  || warn "The App can reach more than $OWNER/$SITE_REPO. Narrow it at https://github.com/settings/installations"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Give each app repo the Client ID and key"
say "Sets on each of: ${APP_REPOS[*]}"
note "  variable SITE_APP_CLIENT_ID = $SITE_APP_CLIENT_ID"
note "  secret   SITE_APP_KEY       = the .pem file, piped from disk"
if confirm "Set them now?"; then
  for repo in "${APP_REPOS[@]}"; do
    if gh variable set SITE_APP_CLIENT_ID -R "$OWNER/$repo" --body "$SITE_APP_CLIENT_ID" >/dev/null \
      && gh secret set SITE_APP_KEY -R "$OWNER/$repo" < "$PEM_PATH" >/dev/null; then
      WRITTEN_SECRET+=("$repo:SITE_APP_KEY")
      printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$repo"
    else
      SKIPPED+=("$repo: gh variable set SITE_APP_CLIENT_ID / gh secret set SITE_APP_KEY < the .pem")
      warn "failed for $repo"
    fi
  done
else
  SKIPPED+=("SITE_APP_CLIENT_ID variable + SITE_APP_KEY secret on ${APP_REPOS[*]}")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Clean up"
old=()
for repo in "${APP_REPOS[@]}"; do
  gh secret list -R "$OWNER/$repo" 2>/dev/null | grep -q '^SITE_DISPATCH_TOKEN\b' && old+=("$repo")
done
if (( ${#old[@]} )); then
  say "The old PAT secret SITE_DISPATCH_TOKEN is still on: ${old[*]}"
  if confirm "Delete it from those repos? (the new workflows no longer read it)"; then
    for repo in "${old[@]}"; do gh secret delete SITE_DISPATCH_TOKEN -R "$OWNER/$repo" && printf '  %s✓ deleted%s on %s\n' "$GREEN" "$RESET" "$repo"; done
  else
    SKIPPED+=("delete SITE_DISPATCH_TOKEN on ${old[*]}")
  fi
else
  note "No SITE_DISPATCH_TOKEN secrets left on the app repos."
fi
say "If you ever made a PAT for site dispatch, revoke it:"
open_url "https://github.com/settings/personal-access-tokens"
say "GitHub can make a new key any time, so the downloaded copy isn't needed."
if confirm "Delete $PEM_PATH?"; then
  rm -f "$PEM_PATH" && printf '  %s✓ deleted%s the local key file\n' "$GREEN" "$RESET"
else
  SKIPPED+=("delete the local key file $PEM_PATH")
fi
pause

finish
say "Next release of an app sends app-released with a one-hour App token; the"
say "'Notify the website' step logs a notice and skips if either value is missing."
